SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Charlie_Chan_in_Honolulu dbr:Lianna }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
}

SELECT ?filmLater ?filmLaterLabel ?directorLater ?directorLaterLabel ?birthDateLater WHERE {
  dbr:Charlie_Chan_in_Honolulu dbo:director ?dir1 .
  dbr:Lianna dbo:director ?dir2 .
  ?dir1 dbo:birthDate ?b1 .
  ?dir2 dbo:birthDate ?b2 .
  BIND(IF(xsd:date(?b1) > xsd:date(?b2), dbr:Charlie_Chan_in_Honolulu, dbr:Lianna) AS ?filmLater)
  BIND(IF(xsd:date(?b1) > xsd:date(?b2), ?dir1, ?dir2) AS ?directorLater)
  BIND(IF(xsd:date(?b1) > xsd:date(?b2), ?b1, ?b2) AS ?birthDateLater)
  OPTIONAL { ?filmLater rdfs:label ?filmLaterLabel FILTER(lang(?filmLaterLabel) = 'en') }
  OPTIONAL { ?directorLater rdfs:label ?directorLaterLabel FILTER(lang(?directorLaterLabel) = 'en') }
}

